content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-26-group-buy-001

=== 用户原始指令 (query.txt) ===
搞个图显示还差3杯起送点开跳到app读日程提醒我快不行了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个图显示还差3杯起送点开跳到app读日程提醒我快不行了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "groupBuy": {
      "title": {
        "type": "string",
        "description": "拼单团购卡片标题。",
        "sampleValue": "拼单起送"
      },
      "remainingText": {
        "type": "string",
        "description": "距离团购起送门槛还差的杯数展示文本。",
        "sampleValue": "还差3杯"
      },
      "summaryText": {
        "type": "string",
        "description": "当前拼单杯数与起送门槛的短摘要。",
        "sampleValue": "当前已拼7/10杯"
      },
      "statusText": {
        "type": "string",
        "description": "团购起送状态的短提醒。",
        "sampleValue": "快到起送点"
      },
      "currentCups": {
        "type": "number",
        "description": "当前已拼杯数，用于进度条。",
        "sampleValue": 7
      },
      "targetCups": {
        "type": "number",
        "description": "达到起送所需总杯数，用于进度条总量。",
        "sampleValue": 10
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityName": {
              "type": "string",
              "description": "日程项类别。",
              "sampleValue": "日程"
            },
            "entityId": {
              "type": "string",
              "description": "日程项唯一标识符。",
              "sampleValue": "calendar_sample_001"
            },
            "title": {
              "type": "string",
              "description": "下一条相关日程标题。",
              "sampleValue": "团购提醒"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间，当天日程使用 HH:MM 格式。",
              "sampleValue": "16:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间，当天日程使用 HH:MM 格式。",
              "sampleValue": "16:45"
            },
            "remindTime": [
              {
                "type": "string",
                "description": "日程提醒时间展示文本。",
                "sampleValue": "提前10分钟"
              }
            ]
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_remind.png",
      "description": "提醒图标，适合表达团购临近起送和日程提醒的告警语义。"
    }
  ]
}

